{
  "name": "riggyz-pets",
  "version": "0.1.2",
  "private": true,
  "type": "module",
  "exports": {
    "./gui-experimental": "./dist/gui-experimental.cjs"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "vite build",
    "dev": "vite build --watch",
    "preview": "vite --host 127.0.0.1",
    "typecheck": "tsc --noEmit",
    "test": "tsx --test src/*.test.ts",
    "generate:pet": "tsx scripts/generate-pet.ts",
    "preversion": "npm test && npm run typecheck",
    "version": "npm run build && git add dist/gui-experimental.cjs"
  },
  "dependencies": {
    "@opencode/plugin": "2.2.0",
    "effect": "4.0.1"
  },
  "devDependencies": {
    "@types/node": "^22.15.3",
    "sharp": "^0.35.5",
    "solid-js": "^1.9.9",
    "tsx": "^4.21.0",
    "typescript": "^5.8.3",
    "vite": "^7.0.0",
    "vite-plugin-solid": "^2.11.0"
  }
}
